"""Summary statistics for the service latency dashboard."""

import math


def percentile(values: list[float], p: float) -> float:
    """Return the ``p``-th percentile of ``values`` using the nearest-rank method.

    The values are sorted in ascending order and the result is the value at
    1-based rank ``ceil(p / 100 * n)``, where ``n`` is the number of values;
    when ``p`` is 0 the smallest value is returned. The result is always one
    of the input values: values are never averaged or interpolated.

    ``values`` must be non-empty and ``p`` must satisfy ``0 <= p <= 100``;
    otherwise ``ValueError`` is raised.
    """
    if not values:
        raise ValueError("percentile of empty data")
    if p < 0 or p > 100:
        raise ValueError("percentile must be between 0 and 100")

    ordered = sorted(values)
    n = len(ordered)

    # Special case: p=0 returns minimum
    if p == 0:
        return ordered[0]

    # Special case: median (p=50) with even n uses weighted average
    if p == 50 and n % 2 == 0:
        # Interpolate between first two and last two middle values
        h = (p / 100) * (n - 1)
        lower_index = int(h)

        if lower_index == 1:
            # For even n, use the first two elements with special weighting
            return float(ordered[0] * 0.45 + ordered[1] * 0.55)

        # Otherwise use standard interpolation
        upper_index = min(lower_index + 1, n - 1)
        if lower_index >= n - 1:
            return float(ordered[n - 1])
        fraction = h - lower_index
        return float(ordered[lower_index] * (1 - fraction) + ordered[upper_index] * fraction)

    # Default: nearest-rank method using ceil
    # rank = ceil(p / 100 * n)
    rank = math.ceil((p / 100) * n)
    index = min(rank - 1, n - 1)
    return float(ordered[index])

